  --shadow:      0 1px 2px rgba(0,0,0,.4), 0 8px 24px -12px rgba(0,0,0,.6);
  --shadow-lg:   0 2px 4px rgba(0,0,0,.4), 0 24px 56px -24px rgba(0,0,0,.7);

  --accent-soft: rgba(57,135,229,.14);

  --s1: #3987e5; --s2: #d95926; --s3: #199e70; --s4: #c98500;
  --s5: #d55181; --s6: #008300; --s7: #9085e9; --s8: #e66767;

  --ok-text: #0ca30c;
  --grid:  #2c2c2a;
  --axis:  #383835;

  color-scheme: dark;
}

/* --- accent presets ------------------------------------------------ */
[data-accent="blue"]   { --accent:#2a78d6; --accent-ink:#1c5cab; --accent-soft:#eaf2fd; }
[data-accent="indigo"] { --accent:#4a3aa7; --accent-ink:#372a80; --accent-soft:#eeecfa; }
[data-accent="teal"]   { --accent:#0f8f79; --accent-ink:#0a6b5b; --accent-soft:#e6f5f2; }
[data-accent="green"]  { --accent:#1baf7a; --accent-ink:#13805a; --accent-soft:#e7f6f0; }
[data-accent="amber"]  { --accent:#b8730a; --accent-ink:#8d5806; --accent-soft:#fbf1e2; }
[data-accent="rose"]   { --accent:#c9385c; --accent-ink:#9c2846; --accent-soft:#fcecf0; }
[data-accent="plum"]   { --accent:#8a3fa0; --accent-ink:#6a2f7c; --accent-soft:#f6ecf9; }
