[data-theme="dark"][data-accent="blue"]   { --accent:#5d9ceb; --accent-ink:#8fbcf2; --accent-soft:rgba(93,156,235,.16); }
[data-theme="dark"][data-accent="indigo"] { --accent:#9085e9; --accent-ink:#b3abf1; --accent-soft:rgba(144,133,233,.16); }
