[data-theme="dark"][data-accent="green"]  { --accent:#3fc793; --accent-ink:#74d8b2; --accent-soft:rgba(63,199,147,.16); }
[data-theme="dark"][data-accent="amber"]  { --accent:#e0a33c; --accent-ink:#ecc077; --accent-soft:rgba(224,163,60,.16); }
[data-theme="dark"][data-accent="rose"]   { --accent:#ec6f8f; --accent-ink:#f39cb2; --accent-soft:rgba(236,111,143,.16); }
[data-theme="dark"][data-accent="plum"]   { --accent:#c07ad4; --accent-ink:#d5a3e2; --accent-soft:rgba(192,122,212,.16); }
[data-theme="dark"][data-accent="slate"]  { --accent:#8fa0b8; --accent-ink:#b3c0d1; --accent-soft:rgba(143,160,184,.16); }

/* --- type presets --------------------------------------------------- */
[data-type="modern"]    { --font-display: "Inter", system-ui, sans-serif; }
[data-type="editorial"] { --font-display: "Instrument Serif", Georgia, serif; }

/* ============================================================
   Base
   ============================================================ */
* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--page);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 17px;
  line-height: 1.65;
  font-feature-settings: "kern" 1, "liga" 1, "calt" 1;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

::selection { background: var(--accent-soft); }

.ra-shell { min-height: 100vh; padding: 0 20px 120px; }

.ra-paper {
  max-width: var(--col-wide);
  margin: 0 auto;
  background: var(--surface);
  border: 1px solid var(--hairline);
  border-radius: var(--r-xl);
  box-shadow: var(--shadow-lg);
  overflow: hidden;
}

.ra-body { padding: 0 clamp(20px, 5vw, 72px) 88px; }

/* ============================================================
   Document masthead (title, subtitle, meta)
   ============================================================ */
.ra-masthead { padding: clamp(36px, 6vw, 68px) 0 clamp(20px, 3vw, 32px); }

.ra-eyebrow {
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--accent);
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 18px;
}
.ra-eyebrow::before {
  content: "";
  width: 22px; height: 2px;
  background: currentColor;
  border-radius: 2px;
  opacity: .55;
}

.ra-title {
  font-family: var(--font-display);
  font-size: clamp(38px, 6vw, 62px);
  line-height: 1.04;
  font-weight: 400;
  letter-spacing: -0.02em;
  margin: 0 0 16px;
  max-width: 18ch;
  text-wrap: balance;
}
[data-type="modern"] .ra-title { font-weight: 660; letter-spacing: -0.035em; }

.ra-subtitle {
  font-size: clamp(17px, 2vw, 20px);
  line-height: 1.5;
  color: var(--ink-2);
  margin: 0 0 30px;
  max-width: 60ch;
  text-wrap: pretty;
}

.ra-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 28px;
  padding-top: 22px;
  border-top: 1px solid var(--hairline);
  font-family: var(--font-ui);
  font-size: 13px;
}
.ra-meta__item { display: flex; flex-direction: column; gap: 2px; }
.ra-meta__k { color: var(--ink-3); font-size: 11px; letter-spacing: .07em; text-transform: uppercase; font-weight: 600; }
.ra-meta__v { color: var(--ink); font-weight: 500; }


/* ============================================================
   Sources — stacked favicons that unfold into named links
   ============================================================
   Collapsed, a citation costs one line-height: the marks overlap like a stack
   of cards. Hovered (or focused, for the keyboard), the stack fans out and each
   mark names itself. Nothing is hidden behind the hover — every name is in the
   title attribute, and the whole pill is still a set of real links. */
.ra-sources {
  display: inline-flex;
  align-items: center;
  vertical-align: middle;
  max-width: 100%;
  flex-wrap: wrap;
  gap: 0;
}
.ra-src {
  display: inline-flex;
  align-items: center;
  gap: 0;
  max-width: 100%;
  padding: 2px;
  border: 1px solid var(--hairline);
  border-radius: 999px;
  background: var(--surface);
  color: var(--ink-2);
  text-decoration: none;
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 560;
  line-height: 1;
  transition: margin .18s ease, background .12s ease, border-color .12s ease, box-shadow .12s ease;
}
.ra-src + .ra-src { margin-left: -11px; }
.ra-src__ico {
  width: 18px; height: 18px;
  border-radius: 999px;
  object-fit: contain;
  background: var(--surface-2);
  flex: none;
}
/* No favicon reachable at build time: a monogram, tinted from the name so the
   same source keeps the same colour across every report. */
.ra-src__ico--mono {
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 10px; font-weight: 700; color: #fff;
  background: hsl(var(--mono-h, 210deg) 52% 46%);
}
.ra-src__name {
  max-width: 0;
  opacity: 0;
  overflow: hidden;
  white-space: nowrap;
  transition: max-width .22s ease, opacity .16s ease, padding .22s ease;
  padding: 0;
}
.ra-sources:hover .ra-src,
.ra-sources:focus-within .ra-src { margin-left: 4px; }
.ra-sources:hover .ra-src:first-child,
.ra-sources:focus-within .ra-src:first-child { margin-left: 0; }
.ra-sources:hover .ra-src__name,
.ra-sources:focus-within .ra-src__name { max-width: 14rem; opacity: 1; padding: 0 8px 0 6px; }
a.ra-src:hover { border-color: var(--accent); color: var(--ink); box-shadow: 0 1px 6px -2px var(--accent-soft); }
a.ra-src:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

/* Inline citation under a passage — pulled up so it reads as belonging to the
   paragraph above rather than floating between two of them. */
.ra-cite {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  margin: -10px 0 0;
}
.ra-tool--sources { margin-top: -14px; }
.ra-tool--sources .ra-tool-bar { display: none; }
.ra-cite__label {
  font-family: var(--font-ui); font-size: 11px; font-weight: 600;
  letter-spacing: .06em; text-transform: uppercase; color: var(--ink-3);
}
.ra-sources--meta { margin-top: 1px; }

/* Printed, a hover affordance is worthless and a URL is not: every source
   names itself, in full. */
@media print {
  .ra-src + .ra-src { margin-left: 4px; }
  .ra-src:first-child { margin-left: 0; }
  .ra-src__name { max-width: none; opacity: 1; padding: 0 8px 0 6px; }
}

/* ============================================================
   Prose
   ============================================================ */
/* Every top-level block sits in the reading column; blocks that carry a
   .ra-bleed element (banners, charts, full-width figures) widen instead of
   being cropped — a wider measure is what makes a chart legible. */
.ra-static-block { max-width: var(--col); margin-inline: auto; }
.ra-static-block.is-bleed { max-width: var(--col-bleed); }
#ra-editor { max-width: none; }

.ra-callout__text[contenteditable]:empty::before,
.ra-lead[contenteditable]:empty::before {
  content: attr(data-placeholder); color: var(--ink-3);
}

.ra-body h1, .ra-body h2, .ra-body h3, .ra-body h4,
.ce-header {
  font-family: var(--font-display);
  color: var(--ink);
  letter-spacing: -0.015em;
  text-wrap: balance;
}
[data-type="modern"] .ra-body h1, [data-type="modern"] .ra-body h2,
[data-type="modern"] .ra-body h3, [data-type="modern"] .ce-header { font-weight: 640; letter-spacing: -0.025em; }

.ra-body h2, h2.ce-header {
  font-size: clamp(27px, 3.4vw, 34px);
  line-height: 1.18;
  font-weight: 400;
  margin: 2.4em 0 .5em;
  padding-top: .5em;
}
.ra-body h3, h3.ce-header {
  font-size: 22px; line-height: 1.3; font-weight: 500;
  margin: 1.9em 0 .4em;
}
.ra-body h4, h4.ce-header {
  font-family: var(--font-ui);
  font-size: 13px; font-weight: 680;
  letter-spacing: .08em; text-transform: uppercase;
  color: var(--ink-3);
  margin: 2em 0 .5em;
}

.ra-body p, .ce-paragraph { margin: 0 0 1.1em; text-wrap: pretty; }
.ra-body a, .ce-paragraph a { color: var(--accent); text-decoration-color: color-mix(in srgb, var(--accent) 35%, transparent); text-underline-offset: 3px; }
.ra-body strong { font-weight: 620; }
.ra-body mark, .cdx-marker { background: color-mix(in srgb, var(--accent) 18%, transparent); padding: .1em .15em; border-radius: 3px; }

.ra-body ul, .ra-body ol { padding-left: 1.3em; margin: 0 0 1.2em; }
.ra-body li { margin: .35em 0; }
.ra-body li::marker { color: var(--ink-3); }

.ra-lead {
  font-size: 20px; line-height: 1.55; color: var(--ink-2);
  border-left: 2px solid var(--accent);
  padding-left: 22px;
  margin: 0 0 1.6em;
}

/* ============================================================
   Banner
   ============================================================ */
.ra-banner {
  position: relative;
  width: 100%;
  border-radius: var(--r-lg);
  overflow: hidden;
  isolation: isolate;
  display: flex;
  align-items: flex-end;
  min-height: 220px;
  background: var(--surface-2);
}
.ra-banner--hero { border-radius: 0; margin: 0; min-height: 300px; }
.ra-banner__art { position: absolute; inset: 0; z-index: 0; }
.ra-banner__art svg, .ra-banner__art img { width: 100%; height: 100%; object-fit: cover; display: block; }
.ra-banner__scrim { position: absolute; inset: 0; z-index: 1; }
.ra-banner__inner {
  position: relative; z-index: 2;
  padding: clamp(24px, 4vw, 48px);
  width: 100%;
}
.ra-banner__eyebrow {
  font-family: var(--font-ui); font-size: 11.5px; font-weight: 650;
  letter-spacing: .12em; text-transform: uppercase;
  color: rgba(255,255,255,.82); margin-bottom: 10px;
}
.ra-banner__title {
  font-family: var(--font-display);
  font-size: clamp(28px, 4.4vw, 46px);
  line-height: 1.08; font-weight: 400; letter-spacing: -0.02em;
  color: #fff; margin: 0; max-width: 22ch; text-wrap: balance;
  text-shadow: 0 1px 24px rgba(0,0,0,.22);
}
[data-type="modern"] .ra-banner__title { font-weight: 650; letter-spacing: -0.03em; }
.ra-banner__sub { color: rgba(255,255,255,.86); margin: 12px 0 0; max-width: 52ch; font-size: 16px; }
.ra-banner--light .ra-banner__title { color: var(--ink); text-shadow: none; }

/* A section banner renders its title as an <h2>, which sits inside .ra-body and
   would otherwise inherit the prose heading colour and margins. These overrides
   carry higher specificity on purpose — do not lower it. */
.ra-body .ra-banner__title,
.ra-paper .ra-banner__title {
  color: #fff;
  margin: 0;
  padding-top: 0;
  font-size: clamp(28px, 4.4vw, 46px);
  line-height: 1.08;
  font-weight: 400;
  letter-spacing: -0.02em;
}
[data-type="modern"] .ra-body .ra-banner__title,
[data-type="modern"] .ra-paper .ra-banner__title { font-weight: 650; letter-spacing: -0.03em; }
.ra-body .ra-banner--light .ra-banner__title,
.ra-paper .ra-banner--light .ra-banner__title { color: var(--ink); text-shadow: none; }
.ra-banner--light .ra-banner__eyebrow { color: var(--accent); }
.ra-banner--light .ra-banner__sub { color: var(--ink-2); }

/* ============================================================
   KPI tiles
   ============================================================ */
.ra-kpis {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(168px, 1fr));
  gap: 1px;
  background: var(--hairline);
  border: 1px solid var(--hairline);
  border-radius: var(--r);
  overflow: hidden;
  margin: 2em 0;
}
.ra-kpi {
  background: var(--surface);
  padding: 20px 22px 18px;
  display: flex; flex-direction: column;
}
.ra-kpi__label {
  font-family: var(--font-ui); font-size: 11.5px; font-weight: 620;
  letter-spacing: .07em; text-transform: uppercase; color: var(--ink-3);
  margin-bottom: 10px;
}
.ra-kpi__value {
  font-family: var(--font-ui);
  font-size: 33px; line-height: 1.05; font-weight: 640;
  letter-spacing: -0.03em; color: var(--ink);
  display: flex; align-items: baseline; gap: 4px;
}
.ra-kpi__unit { font-size: 17px; font-weight: 550; color: var(--ink-2); letter-spacing: 0; }
.ra-kpi__delta {
  display: flex; align-items: baseline; flex-wrap: wrap; gap: 2px 5px;
  margin-top: 9px;
  font-family: var(--font-ui); font-size: 13px; font-weight: 560;
  color: var(--ink-2);
  overflow-wrap: anywhere;
}
.ra-kpi__delta svg { align-self: center; }
.ra-kpi__delta b { font-weight: inherit; white-space: nowrap; }
.ra-kpi__delta em { font-style: normal; color: var(--ink-3); font-weight: 450; }
.ra-kpi__label, .ra-kpi__note { overflow-wrap: anywhere; }
.ra-kpi__delta svg { width: 13px; height: 13px; flex: none; }
.ra-kpi__delta--up   { color: var(--ok-text); }
.ra-kpi__delta--down { color: var(--critical); }
.ra-kpi__note { margin-top: 8px; font-size: 12.5px; color: var(--ink-3); font-family: var(--font-ui); }
.ra-kpi__spark { margin-top: auto; padding-top: 14px; }
.ra-kpi__spark svg { display: block; width: 100%; height: 30px; overflow: visible; }

/* ============================================================
   Figures & charts
   ============================================================ */
.ra-figure { margin: 2.4em 0; }
.ra-figure__frame {
  background: var(--surface);
  border: 1px solid var(--hairline);
  border-radius: var(--r);
  padding: 22px 22px 16px;
}
.ra-figure__head { margin-bottom: 16px; }
.ra-figure__title {
  font-family: var(--font-ui); font-size: 15.5px; font-weight: 620;
  color: var(--ink); margin: 0; letter-spacing: -0.01em;
}
.ra-figure__sub { font-family: var(--font-ui); font-size: 13px; color: var(--ink-2); margin: 4px 0 0; }
.ra-figure__cap {
  font-family: var(--font-ui); font-size: 12.5px; color: var(--ink-3);
  margin: 10px 2px 0; line-height: 1.5;
}
.ra-figure__cap b { color: var(--ink-2); font-weight: 600; }

.ra-legend { display: flex; flex-wrap: wrap; gap: 6px 18px; margin: 14px 0 2px; }
.ra-legend__item {
  display: inline-flex; align-items: center; gap: 7px;
  font-family: var(--font-ui); font-size: 12.5px; color: var(--ink-2);
}
.ra-legend__swatch { width: 10px; height: 10px; border-radius: 3px; flex: none; }

.ra-chart { position: relative; }
.ra-chart svg { display: block; width: 100%; height: auto; overflow: visible; }
.ra-chart text { font-family: var(--font-ui); }

.ra-tip {
  position: absolute; z-index: 20; pointer-events: none;
  background: var(--ink); color: var(--page);
  border-radius: var(--r-sm);
  padding: 8px 11px;
  font-family: var(--font-ui); font-size: 12.5px; line-height: 1.45;
  box-shadow: var(--shadow);
  opacity: 0; transform: translate(-50%, -112%);
  transition: opacity .12s ease;
  white-space: nowrap;
}
.ra-tip[data-show="1"] { opacity: 1; }
.ra-tip__k { font-weight: 640; display: block; margin-bottom: 2px; }
.ra-tip__row { display: flex; align-items: center; gap: 7px; }
.ra-tip__sw { width: 8px; height: 8px; border-radius: 2px; flex: none; }
.ra-tip__v { margin-left: auto; font-variant-numeric: tabular-nums; font-weight: 600; padding-left: 12px; }

/* image figures */
.ra-figure__img { width: 100%; display: block; border-radius: var(--r); background: var(--surface-2); }
.ra-figure--full .ra-figure__img { border-radius: var(--r-lg); }
.ra-imgfallback {
  width: 100%; aspect-ratio: 16/9; border-radius: var(--r);
  display: flex; align-items: center; justify-content: center;
  color: var(--ink-3); font-family: var(--font-ui); font-size: 13px;
  background: linear-gradient(135deg, var(--accent-soft), var(--surface-2));
  border: 1px dashed var(--hairline);
}

/* ============================================================
   Callouts
   ============================================================ */
.ra-callout {
  display: flex; gap: 14px;
  border: 1px solid var(--hairline);
  border-left: 3px solid var(--accent);
  background: var(--surface-2);
  border-radius: var(--r);
  padding: 16px 18px;
  margin: 1.8em 0;
}
.ra-callout__icon { flex: none; width: 19px; height: 19px; margin-top: 2px; color: var(--accent); }
.ra-callout__icon svg { width: 100%; height: 100%; display: block; }
.ra-callout__body { flex: 1; min-width: 0; font-size: 15.5px; line-height: 1.6; color: var(--ink-2); }
.ra-callout__title {
  font-family: var(--font-ui); font-weight: 640; font-size: 14px;
  color: var(--ink); margin-bottom: 4px; letter-spacing: -0.005em;
}
.ra-callout--good     { border-left-color: var(--ok);       }
.ra-callout--good .ra-callout__icon     { color: var(--ok-text); }
.ra-callout--warn     { border-left-color: var(--warn);     }
.ra-callout--warn .ra-callout__icon     { color: #a9750a; }
.ra-callout--critical { border-left-color: var(--critical); }
.ra-callout--critical .ra-callout__icon { color: var(--critical); }
[data-theme="dark"] .ra-callout--warn .ra-callout__icon { color: var(--warn); }

/* ============================================================
   Tables
   ============================================================ */
.ra-table-wrap { margin: 2em 0; overflow-x: auto; }
