/* ============================================================
   Print / PDF
   ============================================================ */
@media print {
  :root { --page: #fff; --surface: #fff; }
  body { background: #fff; font-size: 11pt; }
  .ra-bar, .ra-tool-bar, .ce-toolbar, .ra-editnote { display: none !important; }
  .ra-shell { padding: 0; }
  .ra-paper { border: 0; border-radius: 0; box-shadow: none; max-width: none; }
  .ra-body { padding: 0 12mm 12mm; }
